def __len__(self):
    if self.iterable is None:
        return self.total

    if hasattr(self.iterable, "shape"):
        if isinstance(self.iterable.shape, (list, tuple)):
            return self.iterable.shape[0]
        raise TypeError("Expected 'shape' to be a list or tuple-like.")

    if hasattr(self.iterable, "__len__"):
        return len(self.iterable)

    # Provide feedback for unexpected types
    raise TypeError(f"Unsupported type for iterable: {type(self.iterable)}")
